MULTI="\"\"\"REMURA V32.4 LAB: six-arm tick with content-addressed local evidence.\nNo network. Existing V312 database is read only. No historical capture.\nPersistent mode requires separate owner approval and local permit.\n\"\"\"\nimport os,sys,json,time,sqlite3,stat,fcntl,shutil,hashlib,unittest,tempfile\nfrom pathlib import Path\nfrom contextlib import closing\nBASE=Path.home()/\".remura-v296\"\nHERE=BASE/\"v318\"\nDAY=86400000\ndef clock():return time.time_ns()//1000000\ndef private(p,d=False):\n    s=p.lstat()\n    if s.st_uid!=os.getuid() or stat.S_IMODE(s.st_mode)!=(0o700 if d else 0o600) or not (stat.S_ISDIR(s.st_mode) if d else stat.S_ISREG(s.st_mode)):raise ValueError(\"permissions\")\ndef read(p,cap):\n    private(p)\n    with p.open(\"rb\") as f:b=f.read(cap+1)\n    if not 0<len(b)<=cap:raise ValueError(\"size\")\n    return b\ndef permit_ok(p,now):\n    return type(p) is dict and set(p)=={\"mode\",\"enabled\",\"start_ms\"} and p[\"mode\"]==\"V318_LOCAL_MULTIFACTOR\" and p[\"enabled\"] is True and type(p[\"start_ms\"]) is int and 0<p[\"start_ms\"]<=now\ndef deps():\n    sys.path[:0]=[str(HERE),str(BASE/\"v311\"),str(BASE/\"v312\"),str(BASE/\"v301\"),str(BASE)]\ndef source():\n    p=BASE/\"v312/science-tv.sqlite3\";private(p)\n    db=sqlite3.connect(p.as_uri()+\"?mode=ro\",uri=True,timeout=3)\n    db.execute(\"PRAGMA query_only=ON\")\n    return db\ndef candidate(src,retail_input,rule_hash,proof=None):\n    import v318_multifactor as m\n    from v317_source_join import packet,retail\n    from v311_science import records\n    from v310_multifeed import tv_bar,m15\n    from v294_footprint_cvd import derive\n    from v299_source_correlation import cot_context\n    from v310_science_adapter import prepare\n    if retail_input is None:return \"WAIT_RETAIL\",None\n    cot=read(BASE/\"v301/v303-public-cot.json\",1000000)\n    now=clock()\n    r=retail(retail_input,now)\n    if r[\"status\"]!=\"LOCAL_COLLECTION_FRESH_ORIGIN_UNKNOWN\":return \"WAIT_RETAIL\",None\n    rows=records(src,now,now-DAY)\n    if not rows:return \"WAIT_TV\",None\n    if len(rows)>288:raise ValueError(\"window\")\n    if now-rows[-1][0][\"bar_close_ms\"]>600000:return \"WAIT_TV_FRESH\",None\n    bars=m15([tv_bar(*x,now) for x in rows],now)\n    if not bars:return \"WAIT_M15\",None\n    f=derive([{\"metadata\":a,\"original\":b,\"sha256\":c} for a,b,c in rows],now)\n    if not f:return \"WAIT_FOOTPRINT\",None\n    if f[-1][\"bar_close_ms\"]!=rows[-1][0][\"bar_close_ms\"]:return \"WAIT_LATEST_FOOTPRINT\",None\n    c=cot_context(json.loads(cot),now)\n    b=prepare(rows,now,{\"status\":\"DESCRIPTIVE_ONLY\",**f[-1]},c)\n    if b[\"status\"]!=\"TV_LOCAL_CANDIDATE_ONLY\":return b[\"status\"],None\n    a,raw,h=rows[-1]\n    ctx=packet(a,raw,h,tv_bar(a,raw,h,now),retail_input,now)\n    if m.sides(b[\"sides\"],ctx) is None:return \"WAIT_MATCHED_CONTEXT\",None\n    e={\"input_close_ms\":bars[-1][\"close_ms\"],\"tv_latest_sha256\":h,\"cot_sha256\":m.sha(cot),\n       \"rules_sha256\":rule_hash,\"source_records\":[[a[\"bar_close_ms\"],h] for a,raw,h in rows]}\n    if clock()-now>4500:return \"WAIT_CAPTURE_TIMEOUT\",None\n    p=m.freeze(b,ctx,e,clock)\n    if p is None:return \"WAIT_FREEZE_BOUNDARY\",None\n    # Keep public COT context and exact rule manifest hash in the local packet.\n    p[\"cot_context\"]=c\n    if proof is not None:proof[\"cot\"]=cot\n    return \"READY_LOCAL_UNWITNESSED\",p\ndef parse_retail_input(data,now):\n    from v317_source_join import retail\n    if len(data)>8192:return None,\"RETAIL_INPUT_OVERSIZE\"\n    if not data.strip():return None,\"RETAIL_INPUT_MISSING\"\n    def unique(pairs):\n        out={}\n        for k,v in pairs:\n            if k in out:raise ValueError(\"duplicate_key\")\n            out[k]=v\n        return out\n    try:\n        p=json.loads(data,object_pairs_hook=unique)\n        r=retail(p,now)\n        if r[\"status\"]!=\"LOCAL_COLLECTION_FRESH_ORIGIN_UNKNOWN\":return None,\"RETAIL_COLLECTION_STALE\"\n        if now-p[\"read_ms\"]>120000:return None,\"RETAIL_BRIDGE_STALE\"\n        return p,\"RETAIL_INPUT_OK\"\n    except (ValueError,TypeError,OverflowError,RecursionError):\n        return None,\"RETAIL_INPUT_INVALID\"\n\ndef missing_jobs(db,now):\n    # Every mature missing outcome is retained. No old gap is silently discarded.\n    return db.execute(\"\"\"WITH h(hours) AS (VALUES(1),(4),(24)), c(cost) AS (VALUES(0),(1),(2))\n      SELECT o.id,o.entry_ms,h.hours,c.cost FROM v318_observations o CROSS JOIN h CROSS JOIN c\n      LEFT JOIN v318_outcomes x ON x.id=o.id AND x.hours=h.hours AND x.cost=c.cost\n      WHERE x.id IS NULL AND o.entry_ms+h.hours*3600000<=?\n      AND o.entry_ms+h.hours*3600000>? ORDER BY o.entry_ms+h.hours*3600000 DESC,o.entry_ms,h.hours,c.cost LIMIT 96\"\"\",(now,now-2*DAY)).fetchall()\n# V37.2 recovery selection; preserve all existing observation rules.\ndef v372_select(db,src,now,multi,limit=32):\n    from bisect import bisect_right\n    if type(now) is not int or now<=0 or type(limit) is not int or not 1<=limit<=32:raise ValueError(\"scope\")\n    closes=[t for (t,) in src.execute(\"SELECT close_ms FROM events WHERE close_ms<=? AND received_ms<=? AND seen_ms<=? ORDER BY close_ms\",(now,now,now))]\n    if any(type(t) is not int or t%300000 for t in closes):raise ValueError(\"grid\")\n    obs=\"v318_observations\" if multi else \"observations\"\n    out=\"v318_outcomes\" if multi else \"outcomes\"\n    entry=\"o.entry_ms\" if multi else \"CAST(json_extract(o.packet,'$.entry_ms') AS INTEGER)\"\n    terminal=\"0\" if multi else \"EXISTS(SELECT 1 FROM terminal_missing t WHERE t.id=o.id AND t.hours=h.hours)\"\n    sql=f\"\"\"WITH h(hours) AS (VALUES(1),(4),(24)), c(cost) AS (VALUES(0),(1),(2))\n    SELECT o.id,{entry},h.hours,SUM(1 << c.cost),{terminal}\n    FROM {obs} o CROSS JOIN h CROSS JOIN c LEFT JOIN {out} x\n    ON x.id=o.id AND x.hours=h.hours AND x.cost=c.cost\n    WHERE x.id IS NULL AND {entry}+h.hours*3600000<=?\n    GROUP BY o.id,h.hours ORDER BY {entry}+h.hours*3600000,o.id,h.hours\"\"\"\n    older=[];recent=[];waiting=overdue=ready=0\n    for ident,e,h,mask,old in db.execute(sql,(now,)):\n        if type(e) is not int or e<=0 or e%900000 or not 1<=mask<=7:raise ValueError(\"job_grid\")\n        end=e+h*3600000\n        costs=tuple(c for c in (0,1,2) if mask&(1<<c))\n        aged=end<=now-172800000\n        if aged:overdue+=len(costs)\n        if bisect_right(closes,end)-bisect_right(closes,e)!=h*12:\n            waiting+=1;continue\n        ready+=1\n        target=older if aged else recent\n        if len(target)<limit:target.append((ident,e,h,costs,bool(old)))\n    reserve=max(1,limit//4)\n    picked=older[:reserve]+recent[:limit-reserve]\n    picked+=older[reserve:reserve+limit-len(picked)]\n    picked+=recent[limit-reserve:limit-reserve+limit-len(picked)]\n    return picked,waiting,overdue,ready\n\ndef v372_future(src,entry,h,now):\n    rows=[(json.loads(meta),raw,d) for meta,raw,d in src.execute(\n        \"SELECT metadata,raw,digest FROM events WHERE close_ms>? AND close_ms<=? AND received_ms<=? AND seen_ms<=? ORDER BY close_ms\",\n        (entry,entry+h*3600000,now,now))]\n    if [m[\"bar_close_ms\"] for m,raw,d in rows]!=list(range(entry+300000,entry+h*3600000+1,300000)):\n        raise ValueError(\"coverage_changed\")\n    return rows\n\ndef evaluate_pending(db,src,now,allowed):\n    import v318_multifactor as m\n    from v310_multifeed import tv_bar,m15\n    selected,waiting,overdue,ready=v372_select(db,src,now,True)\n    saved=0\n    for ident,entry,h,costs,terminal in selected:\n        if not allowed():break\n        rows=v372_future(src,entry,h,now)\n        bars=m15([tv_bar(*row,now) for row in rows],now)\n        for c in costs:\n            if not allowed():break\n            status=m.save_outcome(db,ident,bars,now,h,c)\n            if status==\"EVALUATED\":saved+=1\n            elif status!=\"ALREADY_EVALUATED\":raise ValueError(\"unexpected_evaluator_status\")\n    overdue=db.execute(\"\"\"WITH h(hours) AS (VALUES(1),(4),(24)), c(cost) AS (VALUES(0),(1),(2))\n      SELECT COUNT(*) FROM v318_observations o CROSS JOIN h CROSS JOIN c\n      LEFT JOIN v318_outcomes x ON x.id=o.id AND x.hours=h.hours AND x.cost=c.cost\n      WHERE x.id IS NULL AND o.entry_ms+h.hours*3600000<=?\"\"\",(now-2*DAY,)).fetchone()[0]\n    return {\"new_outcome_rows\":saved,\"waiting_batch_rows\":0,\"waiting_unresolved_horizons\":waiting,\"ready_horizons_before_batch\":ready,\"overdue_unresolved_cost_horizons\":overdue}\nEVIDENCE_CAP=16*1024*1024\ndef preserve(root,raw,expected):\n    if hashlib.sha256(raw).hexdigest()!=expected:raise ValueError(\"evidence_digest\")\n    if not os.path.lexists(root):\n        root.mkdir(mode=0o700)\n    private(root,True)\n    target=root/expected\n    if os.path.lexists(target):\n        if read(target,1000000)!=raw:raise ValueError(\"evidence_conflict\")\n        return\n    used=0\n    for p in root.iterdir():\n        private(p)\n        used+=p.stat().st_size\n    if used+len(raw)>EVIDENCE_CAP:raise ValueError(\"evidence_capacity\")\n    fd,tmp=tempfile.mkstemp(prefix=\".stage-\",dir=root)\n    try:\n        with os.fdopen(fd,\"wb\") as f:\n            f.write(raw);f.flush();os.fsync(f.fileno())\n        os.link(tmp,target)\n        dfd=os.open(root,os.O_RDONLY|os.O_DIRECTORY)\n        try:os.fsync(dfd)\n        finally:os.close(dfd)\n    finally:os.unlink(tmp)\n\ndef capture_and_evaluate(db,src,retail_input,rule_hash,allowed,archive=None):\n    import v318_multifactor as m\n    proof={}\n    status,packet=candidate(src,retail_input,rule_hash,proof)\n    if packet and allowed():\n        if archive is None:raise ValueError(\"archive_required\")\n        try:archive(proof[\"cot\"],packet[\"evidence\"][\"cot_sha256\"])\n        except (OSError,ValueError):status=\"WAIT_EVIDENCE_STORAGE\"\n        else:\n            if clock()-packet[\"frozen_ms\"]>5000 or clock()>=packet[\"entry_ms\"]:\n                status=\"WAIT_EVIDENCE_BOUNDARY\"\n            elif allowed():status=m.append(db,packet,clock)\n    return status,evaluate_pending(db,src,clock(),allowed)\n\ndef main(mode):\n    if os.getuid()==0:raise ValueError(\"not_root\")\n    os.umask(0o077);private(BASE,True);private(HERE,True);deps()\n    # The staged manifest pins the runner, join, and existing scientific dependencies.\n    manifest=read(HERE/\"manifest-v324.json\",65536)\n    pins=json.loads(manifest)\n    if not isinstance(pins,dict) or not pins:raise ValueError(\"manifest\")\n    import importlib.util\n    required={\"v324_runner\",\"v318_multifactor\",\"v317_source_join\",\"v311_science\",\"v310_multifeed\",\"v294_footprint_cvd\",\"v299_source_correlation\",\"v310_science_adapter\",\"v303_science_candidate\",\"v300_paired_outcomes\"}\n    if set(pins)!=required:raise ValueError(\"manifest_scope\")\n    pinned={}\n    for name,h in pins.items():\n        p=Path(__file__) if name==\"v324_runner\" else Path(importlib.util.find_spec(name).origin)\n        raw=read(p,1000000)\n        if hashlib.sha256(raw).hexdigest()!=h:raise ValueError(\"pin\")\n        pinned[h]=raw\n    import v318_multifactor as m\n    if mode==\"--tick\":\n        pp=HERE/\"permit.json\"\n        if not pp.exists() or os.path.lexists(HERE/\"STOP\"):return {\"status\":\"DISABLED\"}\n        p=json.loads(read(pp,8192))\n        if not permit_ok(p,clock()):return {\"status\":\"DISABLED\"}\n        def allowed():\n            return not os.path.lexists(HERE/\"STOP\") and pp.exists() and json.loads(read(pp,8192))==p and permit_ok(p,clock())\n    try:\n        retail_input,retail_state=parse_retail_input(sys.stdin.buffer.read(8193),clock())\n    except OSError:\n        retail_input,retail_state=None,\"RETAIL_INPUT_IO_ERROR\"\n    if mode==\"--preview\":\n        with closing(source()) as src:\n            status,packet=candidate(src,retail_input,m.sha(manifest))\n        return {\"status\":status,\"retail_input_status\":retail_state,\"matched_arms\":len(packet[\"sides\"]) if packet else 0,\"prospective_admitted\":False,\"persistent_write\":False}\n    with os.fdopen(os.open(HERE/\"tick.lock\",os.O_CREAT|os.O_RDWR|os.O_NOFOLLOW,0o600),\"r+\") as lock:\n        private(HERE/\"tick.lock\")\n        try:fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)\n        except BlockingIOError:return {\"status\":\"WAIT_LOCK\"}\n        if not allowed():return {\"status\":\"DISABLED\"}\n        if shutil.disk_usage(HERE).free<512*1024*1024:raise ValueError(\"disk\")\n        path=HERE/\"multifactor.sqlite3\"\n        if not os.path.lexists(path):os.close(os.open(path,os.O_CREAT|os.O_EXCL|os.O_WRONLY|os.O_NOFOLLOW,0o600))\n        private(path)\n        with closing(sqlite3.connect(path,timeout=3)) as db,closing(source()) as src:\n            cap=(128*1024*1024)//db.execute(\"PRAGMA page_size\").fetchone()[0]\n            if db.execute(\"PRAGMA max_page_count=\"+str(cap)).fetchone()[0]!=cap:raise ValueError(\"capacity\")\n            m.initialize(db)\n            root=HERE/\"evidence-v324\"\n            def archive(cot,h):\n                for key,raw in pinned.items():preserve(root,raw,key)\n                preserve(root,manifest,m.sha(manifest))\n                preserve(root,cot,h)\n            status,stats=capture_and_evaluate(db,src,retail_input,m.sha(manifest),allowed,archive)\n            return {\"status\":status,\"retail_input_status\":retail_state,**stats,\"observations\":db.execute(\"SELECT COUNT(*) FROM v318_observations\").fetchone()[0],\"outcome_rows\":db.execute(\"SELECT COUNT(*) FROM v318_outcomes\").fetchone()[0],\"prospective_admitted\":False}\nclass Tests(unittest.TestCase):\n    def test_permit(self):\n        p={\"mode\":\"V318_LOCAL_MULTIFACTOR\",\"enabled\":True,\"start_ms\":100}\n        self.assertTrue(permit_ok(p,100));self.assertFalse(permit_ok(p,99));self.assertFalse(permit_ok(dict(p,enabled=False),100))\n    def test_jobs(self):\n        import v318_multifactor as m\n        db=sqlite3.connect(\":memory:\");m.initialize(db)\n        db.execute(\"INSERT INTO v318_observations VALUES(?,?,?,?)\",(\"a\",DAY,DAY-900000,b\"{}\"))\n        self.assertEqual(len(missing_jobs(db,DAY+3600000)),3)\n        self.assertEqual(len(missing_jobs(db,DAY+4*3600000)),6)\n        self.assertEqual(len(missing_jobs(db,DAY+DAY)),9)\n        self.assertEqual(len(missing_jobs(db,4*DAY)),0)\n        db.close()\nclass RetailTests(unittest.TestCase):\n    def test_transport(self):\n        now=4000000\n        p=dict(source=\"Myfxbook Community Outlook\",symbol=\"EURUSD\",\n            collection_ms=now-1000,read_ms=now-1,long_pct=60,short_pct=40,source_sha256=\"a\"*64)\n        enc=lambda x:json.dumps(x).encode()\n        self.assertEqual(parse_retail_input(enc(p),now),(p,\"RETAIL_INPUT_OK\"))\n        for data,status in [(b\"\",\"RETAIL_INPUT_MISSING\"),(b\"{\",\"RETAIL_INPUT_INVALID\"),\n            (b\"x\"*8193,\"RETAIL_INPUT_OVERSIZE\"),(b'{\"a\":1,\"a\":2}',\"RETAIL_INPUT_INVALID\"),\n            (enc(dict(p,source_sha256=1)),\"RETAIL_INPUT_INVALID\"),\n            (enc(dict(p,long_pct=90)),\"RETAIL_INPUT_INVALID\"),\n            (enc(dict(p,collection_ms=1)),\"RETAIL_COLLECTION_STALE\"),\n            (enc(dict(p,collection_ms=now-130000,read_ms=now-121000)),\"RETAIL_BRIDGE_STALE\")]:\n            self.assertEqual(parse_retail_input(data,now),(None,status))\n    def test_missing_retail_evaluates_pending(self):\n        from unittest.mock import patch\n        mod=sys.modules[__name__]\n        db=object();src=object();allow=lambda:True\n        with patch.object(mod,\"evaluate_pending\",return_value={\"new_outcome_rows\":3}) as evaluate:\n            self.assertEqual(capture_and_evaluate(db,src,None,\"a\"*64,allow),\n                (\"WAIT_RETAIL\",{\"new_outcome_rows\":3}))\n            evaluate.assert_called_once()\n            self.assertIs(evaluate.call_args.args[0],db)\n            self.assertIs(evaluate.call_args.args[1],src)\n\nclass EvidenceTests(unittest.TestCase):\n    def test_archive(self):\n        with tempfile.TemporaryDirectory() as d:\n            p=Path(d)/\"evidence\";raw=b\"public cot exact bytes\";h=hashlib.sha256(raw).hexdigest()\n            preserve(p,raw,h);preserve(p,raw,h)\n            self.assertEqual((p/h).read_bytes(),raw)\n            self.assertEqual(len(list(p.iterdir())),1)\n            with self.assertRaises(ValueError):preserve(p,b\"wrong\",h)\n    def test_capture_archives_before_append(self):\n        from unittest.mock import patch\n        import v318_multifactor as m\n        mod=sys.modules[__name__];order=[]\n        raw=b\"cot\";h=hashlib.sha256(raw).hexdigest()\n        def fake(src,retail,rule,proof):\n            proof[\"cot\"]=raw\n            return \"READY_LOCAL_UNWITNESSED\",{\"frozen_ms\":1000,\"entry_ms\":900000,\"evidence\":{\"cot_sha256\":h}}\n        def archive(b,d):\n            self.assertEqual((b,d),(raw,h));order.append(\"archive\")\n        def append(*args):\n            order.append(\"append\");return \"LOCAL_RECORDED_UNWITNESSED\"\n        with patch.object(mod,\"candidate\",side_effect=fake),patch.object(mod,\"clock\",return_value=1001),patch.object(m,\"append\",side_effect=append),patch.object(mod,\"evaluate_pending\",return_value={}):\n            self.assertEqual(capture_and_evaluate(object(),object(),{},h,lambda:True,archive)[0],\"LOCAL_RECORDED_UNWITNESSED\")\n        self.assertEqual(order,[\"archive\",\"append\"])\n        with patch.object(mod,\"candidate\",side_effect=fake),patch.object(mod,\"clock\",return_value=1001),patch.object(m,\"append\") as save,patch.object(mod,\"evaluate_pending\",return_value={\"new_outcome_rows\":1}) as evaluate:\n            def fail(*args):raise OSError(\"storage\")\n            self.assertEqual(capture_and_evaluate(object(),object(),{},h,lambda:True,fail),(\"WAIT_EVIDENCE_STORAGE\",{\"new_outcome_rows\":1}))\n            save.assert_not_called();evaluate.assert_called_once()\n\nif __name__==\"__main__\":\n    if sys.argv[1:]==[\"--test-evidence\"]:\n        deps();unittest.main(argv=[sys.argv[0],\"EvidenceTests\"])\n    elif sys.argv[1:]==[\"--test-retail\"]:\n        deps();unittest.main(argv=[sys.argv[0],\"RetailTests\"])\n    elif sys.argv[1:]==[\"--selftest\"]:\n        deps();unittest.main(argv=[sys.argv[0]])\n    elif sys.argv[1:] in ([\"--preview\"],[\"--tick\"]):\n        try:print(\"V324 RUNNER\",json.dumps(main(sys.argv[1]),sort_keys=True),flush=True)\n        except Exception as e:print(\"V324 RUNNER STOP\",type(e).__name__,flush=True);sys.exit(2)\n    else:raise SystemExit(\"LAB --selftest | --preview | separately authorized --tick\")\n"
SCIENCE="\"\"\"V31.2 LAB — bounded continuation of the V31.1 same-feed ledger.\nOnly a dedicated private copy of the completed pilot may be modified.\nNo scheduler, provider requests or external timestamp.\n\"\"\"\nimport json,sqlite3\nfrom v311_science import records,canonical,digest,observe_tick,ingest,HOURS,COSTS\nfrom v310_science_adapter import outcomes\nM5=300000\nGRACE=48*3600000\ndef prepare(db):\n    names={x[0] for x in db.execute(\"SELECT name FROM sqlite_master WHERE type='table'\")}\n    if not {\"events\",\"observations\",\"outcomes\"}<=names or names-{\"events\",\"observations\",\"outcomes\",\"terminal_missing\"}:raise ValueError(\"schema\")\n    with db:\n        db.execute(\"CREATE TABLE IF NOT EXISTS terminal_missing(id TEXT,hours INTEGER,recorded_ms INTEGER,reason TEXT NOT NULL,PRIMARY KEY(id,hours),FOREIGN KEY(id) REFERENCES observations(id))\")\n        for op in (\"UPDATE\",\"DELETE\"):\n            db.execute(\"CREATE TRIGGER IF NOT EXISTS terminal_missing_no_\"+op.lower()+\" BEFORE \"+op+\" ON terminal_missing BEGIN SELECT RAISE(ABORT,'append_only'); END\")\n# V37.2 recovery selection; preserve all existing observation rules.\ndef v372_select(db,src,now,multi,limit=32):\n    from bisect import bisect_right\n    if type(now) is not int or now<=0 or type(limit) is not int or not 1<=limit<=32:raise ValueError(\"scope\")\n    closes=[t for (t,) in src.execute(\"SELECT close_ms FROM events WHERE close_ms<=? AND received_ms<=? AND seen_ms<=? ORDER BY close_ms\",(now,now,now))]\n    if any(type(t) is not int or t%300000 for t in closes):raise ValueError(\"grid\")\n    obs=\"v318_observations\" if multi else \"observations\"\n    out=\"v318_outcomes\" if multi else \"outcomes\"\n    entry=\"o.entry_ms\" if multi else \"CAST(json_extract(o.packet,'$.entry_ms') AS INTEGER)\"\n    terminal=\"0\" if multi else \"EXISTS(SELECT 1 FROM terminal_missing t WHERE t.id=o.id AND t.hours=h.hours)\"\n    sql=f\"\"\"WITH h(hours) AS (VALUES(1),(4),(24)), c(cost) AS (VALUES(0),(1),(2))\n    SELECT o.id,{entry},h.hours,SUM(1 << c.cost),{terminal}\n    FROM {obs} o CROSS JOIN h CROSS JOIN c LEFT JOIN {out} x\n    ON x.id=o.id AND x.hours=h.hours AND x.cost=c.cost\n    WHERE x.id IS NULL AND {entry}+h.hours*3600000<=?\n    GROUP BY o.id,h.hours ORDER BY {entry}+h.hours*3600000,o.id,h.hours\"\"\"\n    older=[];recent=[];waiting=overdue=ready=0\n    for ident,e,h,mask,old in db.execute(sql,(now,)):\n        if type(e) is not int or e<=0 or e%900000 or not 1<=mask<=7:raise ValueError(\"job_grid\")\n        end=e+h*3600000\n        costs=tuple(c for c in (0,1,2) if mask&(1<<c))\n        aged=end<=now-172800000\n        if aged:overdue+=len(costs)\n        if bisect_right(closes,end)-bisect_right(closes,e)!=h*12:\n            waiting+=1;continue\n        ready+=1\n        target=older if aged else recent\n        if len(target)<limit:target.append((ident,e,h,costs,bool(old)))\n    reserve=max(1,limit//4)\n    picked=older[:reserve]+recent[:limit-reserve]\n    picked+=older[reserve:reserve+limit-len(picked)]\n    picked+=recent[limit-reserve:limit-reserve+limit-len(picked)]\n    return picked,waiting,overdue,ready\n\ndef v372_future(src,entry,h,now):\n    rows=[(json.loads(meta),raw,d) for meta,raw,d in src.execute(\n        \"SELECT metadata,raw,digest FROM events WHERE close_ms>? AND close_ms<=? AND received_ms<=? AND seen_ms<=? ORDER BY close_ms\",\n        (entry,entry+h*3600000,now,now))]\n    if [m[\"bar_close_ms\"] for m,raw,d in rows]!=list(range(entry+300000,entry+h*3600000+1,300000)):\n        raise ValueError(\"coverage_changed\")\n    return rows\n\ndef evaluate_pending(db,now,limit=32,allowed=lambda:True):\n    selected,waiting,overdue,ready=v372_select(db,db,now,False,limit)\n    saved=recovered=0\n    for ident,entry,hours,costs,terminal in selected:\n        if not allowed():break\n        freeze,blob,cot,manifest=db.execute(\"SELECT frozen_ms,packet,cot,manifest FROM observations WHERE id=?\",(ident,)).fetchone()\n        d=json.loads(blob)\n        if digest(blob)!=ident or d[\"frozen_ms\"]!=freeze or d[\"entry_ms\"]!=entry or d[\"cot_sha256\"]!=digest(cot) or d[\"manifest_sha256\"]!=digest(manifest) or d[\"prospective_admitted\"] is not False:raise ValueError(\"packet\")\n        hist=records(db,d[\"capture_ms\"],d[\"capture_ms\"]-86400000)\n        if [[m[\"bar_close_ms\"],sha] for m,raw,sha in hist]!=d[\"source_records\"]:raise ValueError(\"input_integrity\")\n        future=v372_future(db,entry,hours,now)\n        evidence=canonical([[m[\"bar_close_ms\"],sha] for m,raw,sha in future])\n        added=0\n        with db:\n            for cost in costs:\n                if not allowed():break\n                if db.execute(\"SELECT 1 FROM outcomes WHERE id=? AND hours=? AND cost=?\",(ident,hours,cost)).fetchone():continue\n                result=outcomes(d,future,now,cost,hours)\n                if result[\"status\"]!=\"RETROSPECTIVE_ONLY\":raise ValueError(\"evaluator\")\n                db.execute(\"INSERT INTO outcomes VALUES(?,?,?,?,?,?)\",(ident,hours,cost,now,canonical(result),evidence))\n                added+=1\n        saved+=added\n        if terminal and added:recovered+=1\n    return {\"new_outcome_rows\":saved,\"waiting_horizons\":waiting,\"terminal_missing_added\":0,\"recovered_previously_terminal_horizons\":recovered,\"ready_horizons_before_batch\":ready,\"prospective_admitted\":False}\ndef summary(db):\n    return {\"m5\":db.execute(\"SELECT COUNT(*) FROM events\").fetchone()[0],\n       \"local_observations\":db.execute(\"SELECT COUNT(*) FROM observations\").fetchone()[0],\n       \"outcome_rows\":db.execute(\"SELECT COUNT(*) FROM outcomes\").fetchone()[0],\n       \"terminal_missing\":db.execute(\"SELECT COUNT(*) FROM terminal_missing\").fetchone()[0],\n       \"certified_observations\":0,\"prospective_admitted\":False}\n"
def blob(raw):
    return hashlib.sha1(("blob "+str(len(raw))).encode()+bytes([0])+raw).hexdigest()
def setup():
    if os.getuid()==0:raise ValueError("not_root")
    for p,h in ORIGINALS.items():
        if blob((BASE/p).read_bytes())!=h:raise ValueError("original_blob_mismatch:"+p)
    sys.path[:0]=[str(BASE/"v318"),str(BASE/"v311"),str(BASE/"v312"),str(BASE/"v301"),str(BASE)]
    global S,M
    S={"__name__":"v372_synthetic_science"}
    M={"__name__":"v372_synthetic_multi"}
    exec(compile(SCIENCE,"science_candidate.py","exec"),S)
    exec(compile(MULTI,"multi_candidate.py","exec"),M)
def synthetic(entry):
    from v311_science import initialize,canonical,digest
    db=sqlite3.connect(":memory:")
    initialize(db);S["prepare"](db)
    for t in range(entry,entry+3600000,300000):
        close=t+300000
        meta=dict(symbol="FX:EURUSD",timeframe="5",version="0.9.1-cvd-lab",bar_close_ms=close,received_at_ms=close)
        snap=dict(schema="remura.tv.flow.cvd.snapshot.preview.v1",symbol="FX:EURUSD",timeframe="5",version="0.9.1-cvd-lab",feed="FX",bar_open_ms=t,bar_close_ms=close,confirmed=True,realtime=True,quality={"bar_closed":True},ohlc={"open":1.1,"high":1.1002,"low":1.1,"close":1.1002})
        raw=canonical({"schema":"remura.tv.flow.cvd.preview.v1","snapshot":snap})
        db.execute("INSERT INTO events VALUES(?,?,?,?,?,?)",(close,close,close,canonical(meta),raw,digest(raw)))
    db.commit()
    return db
def decision(entry,multi=False):
    import v318_multifactor as m
    from v311_science import canonical,digest
    p=dict(status="TV_LOCAL_CANDIDATE_ONLY",price_source=m.TV,symbol="EURUSD",frozen_ms=entry-5000,capture_ms=entry-5000,entry_ms=entry,source_records=[],cot_sha256=digest(b"cot"),manifest_sha256=digest(b"manifest"),prospective_admitted=False,sides={k:1 for k in (m.ARMS if multi else m.BASE)})
    if multi:p["schema"]="remura.v318.multifactor.local.v1"
    raw=canonical(p)
    return digest(raw),raw
class Tests(unittest.TestCase):
    def test_science_terminal_recovery(self):
        e=86400000;now=e+4*86400000
        with closing(synthetic(e)) as db:
            ident,raw=decision(e)
            db.execute("INSERT INTO observations VALUES(?,?,?,?,?,?)",(ident,e-900000,e-5000,raw,b"cot",b"manifest"))
            db.execute("INSERT INTO terminal_missing VALUES(?,?,?,?)",(ident,1,now-1,"M5_COVERAGE_UNAVAILABLE"));db.commit()
            self.assertEqual(S["evaluate_pending"](db,now)["new_outcome_rows"],3)
            self.assertEqual(db.execute("SELECT COUNT(*) FROM terminal_missing").fetchone()[0],1)
            self.assertEqual(S["evaluate_pending"](db,now)["new_outcome_rows"],0)
    def test_multifactor_old_and_stop(self):
        import v318_multifactor as m
        e=86400000;now=e+4*86400000
        with closing(synthetic(e)) as src,closing(sqlite3.connect(":memory:")) as db:
            m.initialize(db);ident,raw=decision(e,True)
            db.execute("INSERT INTO v318_observations VALUES(?,?,?,?)",(ident,e,e-900000,raw));db.commit()
            self.assertEqual(M["evaluate_pending"](db,src,now,lambda:False)["new_outcome_rows"],0)
            self.assertEqual(M["evaluate_pending"](db,src,now,lambda:True)["new_outcome_rows"],3)
            self.assertEqual(M["evaluate_pending"](db,src,now,lambda:True)["new_outcome_rows"],0)
    def test_missing_bar_no_recovery(self):
        e=86400000;now=e+4*86400000
        with closing(synthetic(e)) as src:
            # A fresh empty ledger is an absent source, not a fabricated closure.
            with closing(sqlite3.connect(":memory:")) as missing:
                missing.execute("CREATE TABLE events(close_ms INTEGER PRIMARY KEY,received_ms INTEGER,seen_ms INTEGER)")
                ident,raw=decision(e)
                src.execute("INSERT INTO observations VALUES(?,?,?,?,?,?)",(ident,e-900000,e-5000,raw,b"cot",b"manifest"));src.commit()
                picked,waiting,overdue,ready=S["v372_select"](src,missing,now,False)
                self.assertEqual((picked,ready),([],0));self.assertEqual(waiting,3)
def stage():
    os.umask(0o077)
    setup()
    result=unittest.TextTestRunner(verbosity=2).run(unittest.defaultTestLoader.loadTestsFromTestCase(Tests))
    if not result.wasSuccessful():raise SystemExit(2)
    root=BASE/"v372-stage"
    root.mkdir(mode=0o700)
    for name,code in (("v324_runner.py",MULTI),("v312_science_continuation.py",SCIENCE)):
        raw=code.encode()
        with (root/name).open("xb") as f:f.write(raw)
        print(name,hashlib.sha256(raw).hexdigest())
    print("V37.2 STAGED ONLY - LIVE UNCHANGED")
if __name__=="__main__":
    if sys.argv[1:]==["--stage"]:stage()
    else:raise SystemExit("--stage")
